export function time(s){const m=s.trim().match(/^(\d{2,}):([0-5]\d):([0-5]\d)[,.](\d{3})$/);return m?((+m[1]*3600 + +m[2]*60 + +m[3])*1000 + +m[4]):NaN}
export function stamp(ms){ms=Math.round(ms);return `${String(Math.floor(ms/3600000)).padStart(2,'0')}:${String(Math.floor(ms/60000)%60).padStart(2,'0')}:${String(Math.floor(ms/1000)%60).padStart(2,'0')},${String(ms%1000).padStart(3,'0')}`}
export function parse(s){const blocks=s.replace(/^\uFEFF/,'').replace(/\r\n?/g,'\n').trim().split(/\n\s*\n/);if(!s.trim())throw Error('This file is empty. Choose an SRT subtitle file.');return blocks.map((block,i)=>{const lines=block.split('\n');if(/^\d+$/.test(lines[0].trim()))lines.shift();const match=lines.shift()?.match(/^(\d{2,}:\d{2}:\d{2}[,.]\d{3})\s*-->\s*(\d{2,}:\d{2}:\d{2}[,.]\d{3})\s*$/);if(!match||!Number.isFinite(time(match[1]))||!Number.isFinite(time(match[2]))||!lines.length)throw Error(`Caption ${i+1} has an invalid SRT format. No captions were imported.`);return {start:time(match[1]),end:time(match[2]),text:lines.join('\n')}})}
export const serialize=rows=>rows.map((r,i)=>`${i+1}\n${stamp(r.start)} --> ${stamp(r.end)}\n${r.text.trim()}`).join('\n\n')+'\n';
export function length(s){return typeof Intl.Segmenter==='function'?[...new Intl.Segmenter(undefined,{granularity:'grapheme'}).segment(s)].length:Array.from(s).length}
export function reflow(s,max){const words=s.trim().split(/\s+/);const lines=[];let line='';for(const w of words){if(line&&length(line+' '+w)>max){lines.push(line);line=w}else line+=(line?' ':'')+w}if(line)lines.push(line);return lines.join('\n')}
export function issues(rows,i,max=32){const r=rows[i],a=[];if(!Number.isFinite(r.start)||!Number.isFinite(r.end)||r.start<0||r.end<=r.start)a.push('Invalid timing: end must be after start.');if(i&&r.start<rows[i-1].start)a.push('Starts before the previous caption.');if(rows.some((q,j)=>j!==i&&q.start<r.end&&q.end>r.start))a.push('Overlaps another caption.');if(r.end>r.start&&r.end-r.start<800)a.push('Less than 0.8 seconds on screen.');if(!r.text.trim())a.push('Caption text is empty.');if(r.text.split('\n').length>2)a.push('More than two lines. Shorten or edit this caption.');if(r.text.split('\n').some(l=>length(l)>max))a.push('Line exceeds your character limit.');return a}
